    private void change(ServerPlayer player, Runnable mutation) {
        if (!controller.inLobby()) {
            player.sendSystemMessage(c("lobby_only"));
            return;
        }
        mutation.run();
        config.save();
        open(player, Page.SETTINGS);
    }

    private void originalTable(
            Menu gui,
            ServerPlayer player,
            int slot,
            String tableId,
            Component name,
            List<Component> lore,
            Runnable click) {
        original(gui, player, slot, OriginalGuiDesign.button(player, tableId), name, lore, click);
    }

    private void original(
            Menu gui,
            ServerPlayer player,
            int slot,
            ItemStack stack,
            Component name,
            List<Component> lore,
            Runnable click) {
        original(gui, player, slot, stack, name, lore, click, false);
    }

    private void original(
            Menu gui,
            ServerPlayer player,
            int slot,
            ItemStack stack,
            Component name,
            List<Component> lore,
            Runnable click,
            boolean selected) {
        if (stack.isEmpty()) return;
        GuiElementBuilder builder = new GuiElementBuilder(stack);
        if (name != null) builder.setComponent(DataComponents.CUSTOM_NAME, name);
        List<Component> renderedLore = new java.util.ArrayList<>();
        if (selected) {
            renderedLore.add(Component.translatable("swrg.gui.select")
                    .withStyle(style -> style.withColor(ChatFormatting.GREEN).withItalic(false)));
            builder.setComponent(DataComponents.ENCHANTMENT_GLINT_OVERRIDE, true);
            var sourceLore = stack.get(DataComponents.LORE);
            if (sourceLore != null) renderedLore.addAll(sourceLore.lines());
        }
        renderedLore.addAll(lore);
        if (!renderedLore.isEmpty()) builder.setLoreRaw(renderedLore);
        if (click != null) {
            builder.setCallback((index, type, action, source) -> {
                if (!controller.canUseMenus() && gui.page != Page.STATS) {
                    gui.getPlayer().sendSystemMessage(c("lobby_only"));
                    return;
                }
                playOriginalClick(player);
                click.run();
            });
        }
        gui.setSlot(slot, builder.build());
    }

    private static Component originalLinksMessage() {
        var discord = Component.translatable("swrg.gui.links.discord")
                .withStyle(style -> style.withColor(ChatFormatting.BLUE).withItalic(false).withUnderlined(true)
                        .withClickEvent(new ClickEvent.OpenUrl(URI.create("https://discord.gg/RVqrP3ZaYV"))));
        Component planetMinecraft = Component.translatable("swrg.gui.links.planet_minecraft")
                .withStyle(style -> style.withColor(ChatFormatting.DARK_GREEN)
                        .withClickEvent(new ClickEvent.OpenUrl(
                                URI.create("https://www.planetminecraft.com/member/swarog/"))));
        return discord.append(planetMinecraft);
    }

    private static void playOriginalClick(ServerPlayer player) {
        if (!player.entityTags().contains("developer")) {
            playMenuSound(player, SoundEvents.UI_BUTTON_CLICK, 2.0f);
        }
    }

    private static void playMenuSound(ServerPlayer player, net.minecraft.core.Holder<net.minecraft.sounds.SoundEvent> sound, float volume) {
        player.connection.send(new net.minecraft.network.protocol.game.ClientboundSoundPacket(
                sound, net.minecraft.sounds.SoundSource.MASTER, player.getX(), player.getY(), player.getZ(),
                volume, 2.0f, player.getRandom().nextLong()));
    }

    private static String mapSourcePage(String id) {
        if (id.endsWith("b")) return "2000b";
        int number = Integer.parseInt(id);
        if (number <= 25) return "2000";
        if (number <= 50) return "2100";
        return "2200";
    }

    private static void copyConfig(GameConfig from, GameConfig to) {
        to.lives = from.lives;
        to.health = from.health;
        to.countdownSeconds = from.countdownSeconds;
        to.stageOneSeconds = from.stageOneSeconds;
        to.stageTwoSeconds = from.stageTwoSeconds;
        to.endingSeconds = from.endingSeconds;
        to.stageOneEvent = from.stageOneEvent;
        to.stageTwoEvent = from.stageTwoEvent;
        to.pvpMode = from.pvpMode;
        to.day = from.day;
        to.vanillaKits = from.vanillaKits;
        to.vanillaSkills = from.vanillaSkills;
        to.lbcKits = from.lbcKits;
        to.lbcSkills = from.lbcSkills;
        to.lbcLevelups = from.lbcLevelups;
        to.lbcLevelupLimit = from.lbcLevelupLimit;
        to.noBorders = from.noBorders;
        to.mapId = from.mapId;
        to.broken = from.broken;
        to.save();
    }

    private static int cycle(int v, int min, int max) {
        return v >= max ? min : Math.max(min, v + 1);
    }

    public enum Page {
        HUB,
        SETTINGS,
        MAPS,
        VANILLA_KITS,
        VANILLA_SKILLS,
        KEY_SHOP,
        STATS,
        LBC_KITS,
        LBC_SKILLS,
        LBC_TRINKETS,
        LBC_LEVELUPS,
        LBC_CHALLENGE,
        COSMETICS,
        CASES,
        BEDWARS
    }

    private static final class Menu extends SimpleGui {
        private Page page;

        private Menu(ServerPlayer player, Page page) {
            super(MenuType.GENERIC_9x3, player, false);
            this.page = page;
        }

        @Override
        public boolean onClick(int index, ClickType type, ContainerInput action, GuiElement element) {
            // Client chest screens predict a pickup. Always correct that prediction,
            // including empty, inert, shift, drag and hotbar-swap clicks.
            getPlayer().containerMenu.sendAllDataToRemote();
            return true;
        }

        @Override
        public void handleException(Throwable exception) {
            // SGui invokes callbacks with remote updates suppressed. Its exception
            // path does not resume them, leaving the client cursor out of sync.
            var menu = getPlayer().containerMenu;
            menu.resumeRemoteUpdates();
            menu.sendAllDataToRemote();
            me.skywars2.SkyWars2.LOGGER.error("Lobby GUI action failed on {}", page, exception);
        }
    }
}

package me.skywars2.game;

import net.minecraft.core.component.DataComponents;
import net.minecraft.core.particles.ParticleTypes;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.protocol.game.ClientboundSoundPacket;
import net.minecraft.server.level.ServerPlayer;
import net.minecraft.sounds.SoundEvents;
import net.minecraft.sounds.SoundSource;
import net.minecraft.util.Mth;
import net.minecraft.world.effect.MobEffectInstance;
import net.minecraft.world.effect.MobEffects;
import net.minecraft.world.entity.Marker;
import net.minecraft.world.item.ItemStack;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.Map;
import java.util.UUID;

/** Native item callbacks and temporary item state, independent of the selected kit. */
public final class LbcItems {
    private static final CompoundTag BROKEN_TOTEM = new CompoundTag();
    static { BROKEN_TOTEM.putInt("broken_totem", 1); }
    private record Rotation(int yaw, int pitch) {}
    private static final Rotation ZERO_ROTATION = new Rotation(0, 0);
    private static final class TurnCurse {
        final ServerPlayer owner;
        int remaining;
        TurnCurse(ServerPlayer owner) { this.owner = owner; }
    }
    private final GameController game;
    private final Map<UUID, TurnCurse> turnCurses = new HashMap<>();
    // Source rotation storage survives curse expiry/death; bound its lifetime to this match.
    private final Map<UUID, Rotation> rotations = new HashMap<>();
    private final ArrayList<TurnCurse> tickBatch = new ArrayList<>();

    public LbcItems(GameController game) { this.game = game; }

    private boolean active(ServerPlayer player) {
        String dimension = player.level().dimension().identifier().toString();
        return game.allowDamage(player) && !game.awaitingRespawn(player.getUUID())
                && !dimension.equals("minecraft:nexus") && !dimension.equals("minecraft:imprinted");
    }

    /** Same point as the source effects_changed advancement; includes splash/cloud/commands. */
    public void effectsChanged(ServerPlayer player) {
        var effect = player.getEffect(MobEffects.RAID_OMEN);
        if (effect == null || effect.getAmplifier() != 43 || !active(player)) return;
        // The original purge clears potion effects and temporary LBC states, never selections
        // or attribute upgrades. Add future item state resets here as their engines are ported.
        player.removeAllEffects();
        player.entityTags().remove("lightningist");
        player.entityTags().remove("greed_cursed");
        clear(player);
    }

    /** Native used_totem runs before vanilla death-protection effects clear all potions. */
    public void usedTotem(ServerPlayer player, ItemStack used) {
        var data = used.get(DataComponents.CUSTOM_DATA);
        if (data == null || !data.matchedBy(BROKEN_TOTEM) || !active(player)) return;
        for (int repeat = 0; repeat < 3; repeat++) {
            sound(player, SoundEvents.GHAST_HURT, 0);
            sound(player, SoundEvents.GHAST_HURT, 1);
            sound(player, SoundEvents.AMBIENT_CAVE.value(), 0);
            sound(player, SoundEvents.AMBIENT_CAVE.value(), 1);
            sound(player, SoundEvents.AMBIENT_CAVE.value(), 2);
        }
        sound(player, SoundEvents.WITHER_SPAWN, 0);
        player.level().sendParticles(player, ParticleTypes.CAMPFIRE_COSY_SMOKE, false, false,
                player.getX(), player.getY() + 1.62, player.getZ(), 5000, 0.5, 0.3, 0.5, 0.05);
        player.addEffect(new MobEffectInstance(MobEffects.BLINDNESS, 120, 10, false, false));
        turnCurses.computeIfAbsent(player.getUUID(), ignored -> new TurnCurse(player)).remaining += 100;
    }

    private static void sound(ServerPlayer player, net.minecraft.sounds.SoundEvent sound, float pitch) {
        player.connection.send(new ClientboundSoundPacket(net.minecraft.core.Holder.direct(sound), SoundSource.MASTER,
                player.getX(), player.getY(), player.getZ(), 1, pitch, player.getRandom().nextLong()));
    }

    /** Only cursed owners are visited. Local stopper queries run only while a curse is active. */
    public void tick() {
        if (turnCurses.isEmpty()) return;
        // Reuse a bounded snapshot: damage can synchronously remove an owner through AFTER_DEATH.
        tickBatch.addAll(turnCurses.values());
        for (TurnCurse curse : tickBatch) {
            ServerPlayer owner = curse.owner;
            UUID id = owner.getUUID();
            if (turnCurses.get(id) != curse) continue;
            if (!active(owner) || !owner.isAlive() || owner.isRemoved()) { clear(owner); continue; }
            if (!owner.level().getEntitiesOfClass(Marker.class, owner.getBoundingBox().inflate(20), marker ->
                    owner.distanceToSqr(marker) <= 400
                            && (marker.entityTags().contains("stopper_magic") || marker.entityTags().contains("stopper"))).isEmpty()) continue;
            Rotation current = new Rotation(Mth.floor(owner.getYRot()), Mth.floor(owner.getXRot()));
            Rotation previous = rotations.getOrDefault(id, ZERO_ROTATION);
            int yaw = current.yaw - previous.yaw, pitch = current.pitch - previous.pitch;
            // Original commands exclude yaw jumps >=180; pitch has no such exclusion.
            if (Math.abs((long) yaw) > 7 && Math.abs((long) yaw) < 180) punish(owner);
            if (Math.abs((long) pitch) > 7) punish(owner);
            rotations.put(id, current);
            if (game.players().get(id).lbcUnlocks.add("lbc:true_advancements/potions/effect_skill_issue")) game.players().save();
            if (--curse.remaining <= 0) turnCurses.remove(id, curse);
        }
        tickBatch.clear();
    }

    private static void punish(ServerPlayer player) {
        player.hurtServer(player.level(), player.damageSources().generic(), 1);
        player.addEffect(new MobEffectInstance(MobEffects.BLINDNESS, 40, 0));
    }

    public int curseTicks(ServerPlayer player) {
        var curse = turnCurses.get(player.getUUID());
        return curse == null ? 0 : curse.remaining;
    }

    public void clear(ServerPlayer player) { turnCurses.remove(player.getUUID()); }
    public void forget(ServerPlayer player) { clear(player); rotations.remove(player.getUUID()); }
    public void stop() { turnCurses.clear(); rotations.clear(); }
}

